Since [Lit](https://lit.dev/) has not [Reactive Controller](https://lit.dev/docs/composition/controllers/), we can leverage it to support for Lit usage with Exome.

New exports:

```ts
import { StoreController } from 'exome/lit'
```

Example usage

```ts
import { Exome } from 'exome'
import { StoreController } from 'exome/lit'
import { LitElement, html } from 'lit'
import { customElement } from 'lit/decorators.js'

class CounterStore extends Exome {
  public count = 0

  public increment() {
    this.count += 1
  }
}

const counter = new CounterStore()

@customElement('lit-app')
export class LitApp extends LitElement {
  // Create the controller and store it
  private readonly counter = new StoreController(this, counter)

  // Use the controller in render()
  render() {
    const { count, increment } = this.counter.store

    return html`
      <h1 @click=${increment}>${count}</h1>
    `
  }
}
```

